/**
 * Single-user auth: one password (APP_PASSWORD) → a long-lived, HMAC-signed session cookie.
 *
 * - The signing key is derived from SESSION_SECRET, APP_PASSWORD and a random per-database salt
 *   (`auth_state.key_salt`, regenerated by a restore), so changing either secret, or restoring an
 *   export, signs every device out — even into a fresh database whose epoch starts over.
 * - Each cookie carries the session epoch it was issued in (stored in `auth_state`). Signing
 *   out bumps the epoch, revoking every cookie issued before ("sign out everywhere").
 * - Cookies slide: an authenticated request re-issues the cookie once less than
 *   RENEW_BELOW_S of its lifetime is left, so a device in daily use never gets signed out.
 * - One cookie can be revoked on its own ("Forget this device"): a hash of the token is kept in
 *   `revoked_sessions` until the token would have expired.
 */
import { createHash, createHmac, randomBytes, timingSafeEqual } from "node:crypto";
import { isIP } from "node:net";
import { getConnInfo } from "@hono/node-server/conninfo";
import { eq, lt, sql } from "drizzle-orm";
import type { Context, MiddlewareHandler } from "hono";
import { deleteCookie, getCookie, setCookie } from "hono/cookie";
import type { Db } from "./db/client";
import { authState, revokedSessions } from "./db/schema";

export const COOKIE = "sv_session";
/** Over HTTPS the cookie uses the `__Host-` prefix: Secure, Path=/, no Domain — it can't be set by a sibling subdomain. */
export const SECURE_COOKIE = `__Host-${COOKIE}`;
export const MAX_AGE_S = 60 * 60 * 24 * 180; // 180 days
export const RENEW_BELOW_S = 60 * 60 * 24 * 90; // re-issue when fewer than 90 days remain

export const cookieName = (secure: boolean) => (secure ? SECURE_COOKIE : COOKIE);

const digest = (v: string) => createHash("sha256").update(v).digest();

export function passwordMatches(input: string, expected: string): boolean {
  return timingSafeEqual(digest(input), digest(expected));
}

/**
 * The cookie-signing key: rotating SESSION_SECRET, changing APP_PASSWORD or a new database salt
 * invalidates every cookie. An empty salt (a database from before salts existed) derives the
 * key exactly as before, so upgrading signs nobody out.
 */
export function deriveSessionKey(sessionSecret: string, password: string, salt = ""): Buffer {
  return createHmac("sha256", sessionSecret)
    .update(`strawvine/session/v2\0${password}${salt ? `\0${salt}` : ""}`)
    .digest();
}

/** A fresh random `auth_state.key_salt`. */
export const newKeySalt = () => randomBytes(24).toString("base64url");

function sign(payload: string, key: Buffer) {
  return createHmac("sha256", key).update(payload).digest("base64url");
}

/** `<expiresAtMs>.<epoch>.<signature>` */
export function makeToken(key: Buffer, epoch: number, now = Date.now()): string {
  const payload = `${now + MAX_AGE_S * 1000}.${epoch}`;
  return `${payload}.${sign(payload, key)}`;
}

export interface TokenInfo {
  expiresAt: number;
  epoch: number;
}

/** The token's claims when the signature is valid and it hasn't expired; otherwise null. */
export function readToken(token: string | undefined, key: Buffer, now = Date.now()): TokenInfo | null {
  if (!token) return null;
  const parts = token.split(".");
  if (parts.length !== 3) return null;
  const [exp, epoch, sig] = parts as [string, string, string];
  if (!/^\d{1,16}$/.test(exp) || !/^\d{1,10}$/.test(epoch)) return null;
  const a = Buffer.from(sig);
  const b = Buffer.from(sign(`${exp}.${epoch}`, key));
  if (a.length !== b.length || !timingSafeEqual(a, b)) return null;
  const expiresAt = Number(exp);
  return expiresAt > now ? { expiresAt, epoch: Number(epoch) } : null;
}

// ---------------------------------------------------------------------------
// Session epoch & key salt
// ---------------------------------------------------------------------------

export interface AuthState {
  epoch: number;
  /** Mixed into the signing key ("" for databases from before salts existed). */
  salt: string;
  /** `tokenHash`es of single session tokens revoked before they expire. */
  revoked?: ReadonlySet<string>;
}

export interface EpochStore {
  current(): Promise<AuthState>;
  /** Revoke every session issued so far; returns the new state. */
  bump(): Promise<AuthState>;
  /** Revoke one session token (by `tokenHash`) until it expires. */
  revoke?(tokenHash: string, expiresAt: Date): Promise<void>;
}

/** What `revoked_sessions` stores for a token: never the token itself. */
export const tokenHash = (token: string) => createHash("sha256").update(token).digest("hex");

/**
 * The epoch, salt and revoked tokens live in Postgres and are cached briefly in memory: the cache
 * is updated immediately on bump/revoke, the TTL only matters with several processes (two dynos,
 * or a restore run from another process). The row is created on first use, with a random salt.
 */
export function dbEpochStore(db: Db, ttlMs = 5_000): EpochStore {
  let cached: { epoch: number; salt: string; revoked: Set<string>; at: number } | null = null;
  const snapshot = (c: NonNullable<typeof cached>): AuthState => ({ epoch: c.epoch, salt: c.salt, revoked: c.revoked });
  const read = async () => {
    const [row] = await db.execute<{ epoch: number; salt: string | null; revoked: string[] | null }>(sql`
      select a.session_epoch as epoch, a.key_salt as salt,
             (select array_agg(r.token_hash) from revoked_sessions r where r.expires_at > now()) as revoked
      from auth_state a where a.id = 1`);
    return row;
  };
  const cols = { epoch: authState.sessionEpoch, salt: authState.keySalt };
  return {
    async current() {
      if (cached && Date.now() - cached.at < ttlMs) return snapshot(cached);
      let row = await read();
      if (!row) {
        await db.insert(authState).values({ id: 1, sessionEpoch: 0, keySalt: newKeySalt() }).onConflictDoNothing();
        row = await read();
      }
      cached = { epoch: row!.epoch, salt: row!.salt ?? "", revoked: new Set(row!.revoked ?? []), at: Date.now() };
      return snapshot(cached);
    },
    async bump() {
      const [row] = await db
        .insert(authState)
        .values({ id: 1, sessionEpoch: 1, keySalt: newKeySalt() })
        .onConflictDoUpdate({ target: authState.id, set: { sessionEpoch: sql`${authState.sessionEpoch} + 1`, updatedAt: new Date() } })
        .returning(cols);
      // Every revoked token is from an older epoch now; the next read prunes nothing it needs.
      cached = { epoch: row!.epoch, salt: row!.salt ?? "", revoked: cached?.revoked ?? new Set(), at: Date.now() };
      return snapshot(cached);
    },
    async revoke(hash, expiresAt) {
      await db.transaction(async (tx) => {
        await tx.delete(revokedSessions).where(lt(revokedSessions.expiresAt, new Date()));
        await tx.insert(revokedSessions).values({ tokenHash: hash, expiresAt }).onConflictDoNothing();
      });
      if (cached) cached = { ...cached, revoked: new Set([...cached.revoked, hash]) };
    },
  };
}

// ---------------------------------------------------------------------------
// Cookies & middleware
// ---------------------------------------------------------------------------

export interface SessionConfig {
  /** The signing key for a database salt (see `deriveSessionKey`). */
  keyFor: (salt: string) => Buffer;
  secure: boolean;
  epochs: EpochStore;
}

/** `keyFor` for a secret + password, remembering the last salt's key. */
export function sessionKeys(sessionSecret: string, password: string): (salt: string) => Buffer {
  let last: { salt: string; key: Buffer } | null = null;
  return (salt) => {
    if (last?.salt !== salt) last = { salt, key: deriveSessionKey(sessionSecret, password, salt) };
    return last.key;
  };
}

export async function setSessionCookie(c: Context, cfg: SessionConfig, state?: AuthState) {
  const { epoch, salt } = state ?? (await cfg.epochs.current());
  setCookie(c, cookieName(cfg.secure), makeToken(cfg.keyFor(salt), epoch), {
    httpOnly: true,
    secure: cfg.secure,
    sameSite: "Lax",
    path: "/",
    maxAge: MAX_AGE_S,
  });
}

export function clearSessionCookie(c: Context, cfg: Pick<SessionConfig, "secure">) {
  deleteCookie(c, cookieName(cfg.secure), { path: "/", secure: cfg.secure });
  // Cookies issued before the `__Host-` prefix was adopted.
  if (cfg.secure && getCookie(c, COOKIE) !== undefined) deleteCookie(c, COOKIE, { path: "/" });
}

/** The valid session on this request (signature, expiry and epoch check out, not revoked), or null. */
export async function currentSession(
  c: Context,
  cfg: SessionConfig,
): Promise<(TokenInfo & { salt: string; epochs: AuthState; token: string }) | null> {
  const state = await cfg.epochs.current();
  const token = getCookie(c, cookieName(cfg.secure));
  const info = readToken(token, cfg.keyFor(state.salt));
  if (!info || info.epoch !== state.epoch) return null;
  if (state.revoked?.size && state.revoked.has(tokenHash(token!))) return null;
  return { ...info, salt: state.salt, epochs: state, token: token! };
}

export function requireAuth(cfg: SessionConfig): MiddlewareHandler {
  return async (c, next) => {
    const session = await currentSession(c, cfg);
    if (!session) return c.json({ error: "unauthorized" }, 401);
    if (session.expiresAt - Date.now() < RENEW_BELOW_S * 1000) await setSessionCookie(c, cfg, session.epochs);
    await next();
  };
}

// ---------------------------------------------------------------------------
// Known devices
// ---------------------------------------------------------------------------

/**
 * A device that has signed in successfully gets a long-lived, signed "known device" cookie
 * (separate from the session, kept across sign-outs). The login limiter keys a known device by
 * its id instead of its network and exempts it from the global tarpit, so the owner can always
 * sign in from their own phone while someone else is guessing. The key depends on SESSION_SECRET
 * and APP_PASSWORD: a password change forgets every device.
 */
export const DEVICE_COOKIE = "sv_device";
export const DEVICE_MAX_AGE_S = 60 * 60 * 24 * 400; // browsers cap cookie lifetimes at 400 days
export const deviceCookieName = (secure: boolean) => (secure ? `__Host-${DEVICE_COOKIE}` : DEVICE_COOKIE);

export function deriveDeviceKey(sessionSecret: string, password: string): Buffer {
  return createHmac("sha256", sessionSecret).update(`strawvine/device/v1\0${password}`).digest();
}

/** The known-device id on this request when its signature checks out, else null. */
export function knownDevice(c: Context, key: Buffer, secure: boolean): string | null {
  const raw = getCookie(c, deviceCookieName(secure));
  const m = raw ? /^([A-Za-z0-9_-]{16,32})\.([A-Za-z0-9_-]{43})$/.exec(raw) : null;
  if (!m) return null;
  const a = Buffer.from(m[2]!);
  const b = Buffer.from(sign(`device.${m[1]}`, key));
  return a.length === b.length && timingSafeEqual(a, b) ? m[1]! : null;
}

/** Marks this browser as a known device (keeps its id when it already is one). */
export function setDeviceCookie(c: Context, key: Buffer, secure: boolean, id = randomBytes(16).toString("base64url")) {
  setCookie(c, deviceCookieName(secure), `${id}.${sign(`device.${id}`, key)}`, {
    httpOnly: true,
    secure,
    sameSite: "Lax",
    path: "/",
    maxAge: DEVICE_MAX_AGE_S,
  });
}

// ---------------------------------------------------------------------------
// Login rate limiting
// ---------------------------------------------------------------------------

/**
 * The client address for rate limiting. Behind Heroku's router (TRUST_PROXY) the real client
 * IP is the *last* X-Forwarded-For entry — earlier ones are client-supplied. Otherwise the
 * header is ignored and the socket address is used.
 */
export function clientIp(c: Context, trustProxy: boolean): string {
  if (trustProxy) {
    const last = c.req.header("x-forwarded-for")?.split(",").at(-1)?.trim();
    if (last) return last;
  }
  try {
    return getConnInfo(c).remote.address ?? "unknown";
  } catch {
    return "unknown"; // not running on a Node socket (tests)
  }
}

/**
 * The rate-limiting key for a client address: IPv4 by /24 and IPv6 by /64 (one subscriber's
 * allocation), so hopping between addresses in a block doesn't reset the count.
 */
export function clientKey(ip: string): string {
  const mapped = /^::ffff:(\d+\.\d+\.\d+\.\d+)$/i.exec(ip);
  if (mapped) ip = mapped[1]!;
  const v = isIP(ip);
  if (v === 4) return `${ip.split(".").slice(0, 3).join(".")}.0/24`;
  if (v === 6) {
    const [head = "", tail = ""] = ip.toLowerCase().split("%")[0]!.split("::");
    const h = head ? head.split(":") : [];
    const t = tail ? tail.split(":") : [];
    const groups = ip.includes("::") ? [...h, ...Array<string>(8 - h.length - t.length).fill("0"), ...t] : h;
    return `${groups
      .slice(0, 4)
      .map((g) => g.replace(/^0+(?=.)/, ""))
      .join(":")}::/64`;
  }
  return ip;
}

export interface LoginLimiterOptions {
  /** Failed attempts allowed per client (network block or known device) within `windowMs`. */
  perClient?: number;
  windowMs?: number;
  /** Failures across all clients within `globalWindowMs` before unknown clients are slowed down. */
  global?: number;
  globalWindowMs?: number;
  /** First tarpit delay; doubles with every further failure, up to `maxDelayMs`. */
  baseDelayMs?: number;
  /** Longest an attempt waits in the tarpit; when the queue is longer the attempt is refused. */
  maxDelayMs?: number;
}

export type LoginCheck = { ok: true; waitMs: number } | { ok: false; retryAfterS: number };

/**
 * In-memory limiter for the login endpoint. Only failures count; stale entries are pruned.
 *
 * - Per client: `perClient` failures within `windowMs` blocks that client (429).
 * - Globally: once `global` failures pile up within `globalWindowMs` (distributed guessing),
 *   attempts from clients that aren't known devices go through a tarpit — serialised, each
 *   waiting a delay that doubles with every further failure, capped at `maxDelayMs` — instead of
 *   a hard block that would lock the owner out too. An attempt that would queue longer than the
 *   cap is refused. Known devices skip the tarpit.
 */
export function loginLimiter({
  perClient = 10,
  windowMs = 15 * 60_000,
  global = 50,
  globalWindowMs = 60 * 60_000,
  baseDelayMs = 500,
  maxDelayMs = 10_000,
}: LoginLimiterOptions = {}) {
  const failures = new Map<string, number[]>();
  let globalFailures: number[] = [];
  let lastPrune = 0;
  /** When the tarpit is next free. */
  let tarpitFreeAt = 0;

  const prune = (now: number) => {
    lastPrune = now;
    globalFailures = globalFailures.filter((t) => now - t < globalWindowMs);
    for (const [key, times] of failures) {
      const recent = times.filter((t) => now - t < windowMs);
      if (recent.length) failures.set(key, recent);
      else failures.delete(key);
    }
  };

  /** Whether (and after how long) a login attempt from `key` may proceed. */
  function check(key: string, { known = false } = {}, now = Date.now()): LoginCheck {
    if (now - lastPrune > 60_000) prune(now);
    const mine = (failures.get(key) ?? []).filter((t) => now - t < windowMs);
    if (mine.length >= perClient) return { ok: false, retryAfterS: Math.max(1, Math.ceil((mine[0]! + windowMs - now) / 1000)) };
    if (known) return { ok: true, waitMs: 0 };
    const over = globalFailures.filter((t) => now - t < globalWindowMs).length - global;
    if (over < 0) return { ok: true, waitMs: 0 };
    const step = Math.min(maxDelayMs, baseDelayMs * 2 ** Math.min(over, 30));
    const startAt = Math.max(now, tarpitFreeAt);
    const waitMs = startAt + step - now;
    if (waitMs > maxDelayMs) return { ok: false, retryAfterS: Math.max(1, Math.ceil((startAt - now) / 1000)) };
    tarpitFreeAt = startAt + step;
    return { ok: true, waitMs };
  }

  return {
    check,
    /** Whether `key` is blocked outright (its own failures), ignoring the global tarpit. */
    blocked: (key: string, now = Date.now()) => !check(key, { known: true }, now).ok,
    fail(key: string, now = Date.now()) {
      const list = failures.get(key);
      if (list) list.push(now);
      else failures.set(key, [now]);
      globalFailures.push(now);
    },
    succeed(key: string) {
      failures.delete(key);
    },
    /** For tests: number of clients currently tracked. */
    size: () => failures.size,
  };
}
